		int flags = 0;
		flags = Bits.setFlag(flags, 0x01, !rawSubtitle.isEmpty());
		flags = Bits.setFlag(flags, 0x02, !rawDescription.isEmpty());
		flags = Bits.setFlag(flags, 0x04, size != 0D);
		flags = Bits.setFlag(flags, 0x08, !guidePage.isEmpty());
