			if (d.invalid)
			{
				data.writeInt(0);
			}
			else
			{
				data.writeInt(d.id);
			}
		}

		data.writeDouble(size);

		if (minWidth > 0)
		{
			data.writeVarInt(minWidth);
		}
	}

